// Reference data read earlier in this workflow
const leads = $('Receive Leads').all().map(item => item.json);
const experience = $('Get Experience').all().map(item => item.json);
const settingsRows = $('Get Settings').all().map(item => item.json);
const englishSamples = $('Get English Samples').all().map(item => item.json.samples);
const spanishSamples = $('Get Spanish Samples').all().map(item => item.json.samples);

// The experience table as plain text, one line per row
const experienceText = experience
  .map(row => '- ' + row.title + (row.period ? ' (' + row.period + ')' : '') + ': ' + row.text)
  .join('\n');

const results = [];

for (const lead of leads) {
  // Stop if the setup is broken (missing settings or data), so nothing gets written.
  // These are configuration errors, not problems with one lead.
  const settings = settingsRows.find(s => s.tag === lead.tag);
  if (!settings) throw new Error('No settings row for tag ' + lead.tag);

  if (lead.language !== 'Spanish' && lead.language !== 'English') {
    throw new Error('Invalid language for ' + lead.companyName + ': ' + lead.language);
  }
  if (!lead.companyFacts) throw new Error('No company facts for ' + lead.companyName);

  // Pick the samples in the language of the lead
  const isSpanish = lead.language === 'Spanish';
  const samplesText = (isSpanish ? spanishSamples : englishSamples).join('\n\n---\n\n');

  // The explanation block is optional: some tags have one, others do not.
  // An empty text means the email ends with the model's body only.
  const explanation = String(
    (isSpanish ? settings.explanationSpanish : settings.explanationEnglish) || ''
  ).trim();

  results.push({
    json: {
      ...lead,
      jobGoal: settings.jobGoal,
      experienceText: experienceText,
      samplesText: samplesText,
      explanation: explanation
    }
  });
}

return results;

