// The lead with everything the writer received
const lead = $('Build Writing Inputs').item.json;

const subject = String($json.output?.subject || '').trim();
const body = String($json.output?.body || '').trim();

// Collect every problem we find. An empty list means the email is good.
const problems = [];

// Subject: present and short
if (subject === '') problems.push('empty subject');
if (subject.length > 90) problems.push('subject too long');

// Length: the prompt asks for 90 to 140 words. We allow a small margin.
const words = body.split(/\s+/).filter(w => w !== '').length;
if (words < 70 || words > 160) problems.push('body has ' + words + ' words');

// Leftover placeholders, brackets or lists
if (/[{}\[\]]/.test(subject + body)) problems.push('placeholder or bracket left in the text');
if (/^\s*[-*•]\s/m.test(body)) problems.push('list in the body');

// He must introduce himself by name
if (!body.includes('Miguel Hervás')) problems.push('name missing');

// Register: no exclamation marks in English
if (lead.language === 'English' && (subject + body).includes('!')) {
  problems.push('exclamation mark');
}

// Register: Spanish emails use "tú" and "vosotros", never "usted".
// The letter checks around the word make sure it only matches the whole word.
const formal = /(?<!\p{L})(usted|ustedes)(?!\p{L})/iu;
if (lead.language === 'Spanish' && formal.test(subject + body)) {
  problems.push('formal "usted" form');
}

// Drop the long helper fields, but keep the explanation: the sending step needs it
const { experienceText, samplesText, jobGoal, ...rest } = lead;

return {
  json: {
    ...rest,
    emailSubject: subject,
    emailBody: body,
    emailProblems: problems.join('; ')
  }
};
